-- FinSight AI: SEC EDGAR XBRL companyconcept sources for Zetaris Lightning.
-- Generated by scripts/zetaris_setup.py --write-sql. Pattern copied from Zetaris's verified recipe
-- getting-started/open_data/rest_apis/sql/rate_limited/01_edgar_company_facts_create.sql.
-- Replace YOUR_APP_NAME YOUR_CONTACT_EMAIL with your own 'app_name contact@email' (SEC requires it).
-- Run ONE statement at a time in the SQL Editor; some companies do not report every concept
-- (their REST tables return 404) - scripts/zetaris_setup.py --apply skips those automatically.
-- CREATE SCHEMASTORE CONTAINER has no IF NOT EXISTS; comment it out if it already exists.

CREATE LIGHTNING DATABASE FINSIGHT_SEC DESCRIBE BY "FinSight AI SEC EDGAR XBRL companyconcept REST source";

CREATE SCHEMASTORE CONTAINER finsight;

-- Apple Inc. (AAPL) Revenue: us-gaap:RevenueFromContractWithCustomerExcludingAssessedTax
CREATE LIGHTNING REST TABLE aapl_rev_asc606_facts FROM FINSIGHT_SEC REQUEST(
    endpoint "https://data.sec.gov/api/xbrl/companyconcept/CIK0000320193/us-gaap/RevenueFromContractWithCustomerExcludingAssessedTax.json",
    method "get",
    response_type "json",
    http_encoding "URLENCODED"
) HEADER (
    user-agent "YOUR_APP_NAME YOUR_CONTACT_EMAIL"
) BODY ();

CREATE SCHEMASTORE VIEW aapl_rev_asc606 WITH CONTAINER finsight AS
SELECT
    cik,
    `entityName` AS entity_name,
    tag AS concept,
    fact.`start` AS period_start,
    fact.`end` AS period_end,
    fact.val AS value_usd,
    fact.accn AS accession_number,
    fact.fy AS fiscal_year,
    fact.fp AS fiscal_period,
    fact.frame AS period_frame,
    fact.form AS form_type,
    fact.filed AS filed_date
FROM finsight_sec.aapl_rev_asc606_facts
LATERAL VIEW explode(units.USD) AS fact;

